WITH a AS (
  SELECT geometry FROM lisbon_places WHERE names.primary = 'Nicolau Lisboa' ORDER BY id LIMIT 1
), b AS (
  SELECT geometry FROM lisbon_places WHERE names.primary = 'Zip Gum Boogie' ORDER BY id LIMIT 1
)
SELECT ST_Distance_Spheroid(a.geometry, b.geometry) AS distance_m
FROM a, b;

WITH a AS (
  SELECT geometry FROM lisbon_places WHERE names.primary = 'Nicolau Lisboa' ORDER BY id LIMIT 1
), b AS (
  SELECT geometry FROM lisbon_places WHERE names.primary = 'Cafetaria Estado D''Alma' ORDER BY id LIMIT 1
), c AS (
  SELECT geometry FROM lisbon_places WHERE names.primary = 'Zip Gum Boogie' ORDER BY id LIMIT 1
)
SELECT ST_Distance_Spheroid(a.geometry, b.geometry) + ST_Distance_Spheroid(b.geometry, c.geometry) AS total_length_m
FROM a, b, c;

SELECT ST_Area_Spheroid(ST_ConvexHull(ST_Union_Agg(geometry))) / 1000000 AS area_sqkm
FROM lisbon_places
WHERE basic_category = 'cafe';

SELECT ST_Length_Spheroid(ST_Boundary(ST_ConvexHull(ST_Union_Agg(geometry)))) / 1000 AS perimeter_km
FROM lisbon_places
WHERE basic_category = 'restaurant';

SELECT ST_Area_Spheroid(ST_Envelope(ST_Union_Agg(geometry))) AS area_sqm
FROM lisbon_places
WHERE basic_category = 'second_hand_store';
